w("function FuelBar({ value, capacity }: { value: number; capacity: number }) {")
w('  const pct = Math.round((value / capacity) * 100); const col = pct <= 20 ? TH.err : pct <= 40 ? TH.warn : TH.ok')
w('  return <div className="ftp-fuel-bar flex items-center gap-1.5"><div className="w-16 h-2 rounded-full bg-gray-200 dark:bg-gray-700 overflow-hidden"><div className="h-full rounded-full transition-all" style={{ width: pct + "%", backgroundColor: col }}/></div><span className="text-[10px] font-bold" style={{ color: col }}>{pct}%</span></div>')
