w('          {compData.map((c: any) => <tr key={c.id} className="border-b hover:bg-violet-50/50 dark:hover:bg-violet-900/10 dpe-table-row"><td className="p-1.5 font-mono">{c.id}</td><td className="p-1.5"><CompetitorBadge name={c.competitor}/></td><td className="p-1.5"><ServiceBadge type={c.service}/></td><td className="p-1.5">{c.lane}</td><td className="p-1.5 font-semibold">\\u20b9{c.theirRate.toFixed(2)}</td><td className="p-1.5 font-semibold">\\u20b9{c.ourRate.toFixed(2)}</td><td className="p-1.5"><span className={"font-bold " + (c.diff > 0 ? "text-emerald-600" : c.diff < 0 ? "text-red-600" : "text-gray-500")}>{c.diff > 0 ? "+" : ""}{c.diff}%</span></td><td className="p-1.5"><div className="dpe-share-bar w-12 h-2 rounded-full bg-gray-200 dark:bg-gray-700 overflow-hidden"><div className="h-full rounded-full" style={{ width: c.marketShare + "%", backgroundColor: TH.pri }}/></div><span className="text-[10px] ml-1">{c.marketShare}%</span></td><td className="p-1.5">{c.trend === "up" ? <TrendingUp className="w-3 h-3 text-emerald-500"/> : c.trend === "down" ? <TrendingDown className="w-3 h-3 text-red-500"/> : <ArrowRightLeft className="w-3 h-3 text-gray-400"/>}</td></tr>)}')
w('          </tbody></table></div></CardContent></Card>')
w('      </TabsContent>')
w()
