w('          <Card className="dpe-chart-card"><CardHeader className="p-2 pb-0"><CardTitle className="text-xs">Service Type Distribution</CardTitle></CardHeader><CardContent className="p-2"><PieChart height={200}><Pie data={SERVICE_TYPES.map((s, i) => ({ name: s.replace(/_/g, " "), value: ri(5, 30, i + 701) }))} cx="50%" cy="50%" outerRadius={60} dataKey="value" label><Cell fill={PC[0]}/><Cell fill={PC[1]}/><Cell fill={PC[2]}/><Cell fill={PC[3]}/><Cell fill={PC[4]}/><Cell fill={PC[5]}/><Cell fill={PC[6]}/><Cell fill={PC[7]}/></Pie><Tooltip contentStyle={{ fontSize: 11 }}/></PieChart></CardContent></Card>')
w('        </div>')
w('      </TabsContent>')
w()
w('      {/* Insights */}')
w('      <TabsContent value="insights" className="space-y-4">')
w('        <ModuleBreadcrumb items={[{ label: "Dashboard" }, { label: "Insights" }]}/>')
